!function(e){"use strict";function t(e,t){r[e]=t}function i(e){return String(e).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#039;")}function o(){return(e.location.pathname.split("/").pop()||"").replace(/\.html$/,"")||"index"}function n(e,t){return'<ul class="'+t+'">'+e.map(function(e){return"<li>"+i(e)+"</li>"}).join("")+"</ul>"}function a(){const e=r[o()],t=document.querySelector("main.page");if(!e||!t||t.querySelector(".undergrad-guide"))return;const a=document.createElement("section");a.className="undergrad-guide",a.id="undergrad-guide",a.setAttribute("aria-labelledby","undergrad-guide-title"),a.innerHTML='<header class="undergrad-guide__head"><span>CS undergraduate bridge</span><h2 id="undergrad-guide-title">'+i(e.title)+"</h2><p>"+i(e.intro)+'</p></header><div class="undergrad-guide__contract"><article><span>problem</span><p>'+i(e.goal)+"</p></article><article><span>returns</span><p>"+i(e.output)+'</p></article></div><div class="undergrad-guide__foundations"><article><h3>Bring these ideas</h3>'+n(e.prerequisites,"undergrad-guide__prereqs")+"</article><article><h3>Symbols on this page</h3><table><tbody>"+e.symbols.map(function(e){return"<tr><th>"+i(e[0])+"</th><td>"+i(e[1])+"</td></tr>"}).join("")+'</tbody></table></article></div><div class="undergrad-guide__algorithm"><div><h3>The algorithm, before the details</h3><ol class="undergrad-guide__phases">'+e.phases.map(function(e){return"<li><strong>"+i(e[0])+"</strong><span>"+i(e[1])+"</span></li>"}).join("")+'</ol></div><div class="undergrad-guide__code"><div><span>pseudocode</span><small>names match the walker</small></div><pre><code>'+i(e.pseudocode.join("\n"))+'</code></pre></div></div><div class="undergrad-guide__reasoning"><article><span>invariant to watch</span><p>'+i(e.invariant)+"</p></article><article><span>cost model</span><p>"+i(e.complexity)+'</p></article></div><article class="undergrad-guide__example"><span>tiny worked example \xb7 '+i(e.example.title)+"</span><div><p><strong>Input.</strong> "+i(e.example.input)+"</p><p><strong>Trace.</strong> "+i(e.example.trace)+"</p><p><strong>Output.</strong> "+i(e.example.output)+'</p></div></article><div class="undergrad-guide__bottom"><article><span>common wrong turn</span><p><del>'+i(e.misconception[0])+"</del><br>"+i(e.misconception[1])+'</p></article><details><summary>Check your understanding</summary><p class="undergrad-guide__question">'+i(e.checkpoint[0])+"</p><p><strong>Answer.</strong> "+i(e.checkpoint[1])+'</p></details></div><p class="undergrad-guide__production"><strong>When you compare with the repository:</strong> '+i(e.production)+"</p>";const s=t.querySelector(".deep-audit")||t.querySelector(".lesson-guide, .hook, section.stage");t.insertBefore(a,s)}const r={};t("leiden-cpm",{title:"Leiden CPM as a sequence of local state changes",intro:"Think of Leiden as an optimizer wrapped around a score. CPM supplies the score; Leiden supplies the move, refine, and compress loop that searches for a better partition.",goal:"Partition an undirected graph into groups whose internal edge density is high relative to a user-chosen resolution \u03b3.",output:"One community label per retained vertex. The repository removes singleton communities before writing com.csv.",prerequisites:["Adjacency lists, weighted degrees, and connected components","A partition: an array membership[v] that assigns every vertex to one block","Greedy local search: accept a change when its objective gain is positive"],symbols:[["e_c","total weight of edges whose two endpoints are in community c"],["n_c","number of vertices in community c"],["\u03b3","resolution penalty paid for each possible within-community pair"],["\u0394H(v\u2192c)","change in CPM score if vertex v moves to community c"]],phases:[["Score","Fix \u03b3 and define H = \u03a3_c[e_c \u2212 \u03b3 n_c(n_c\u22121)/2]."],["Move","Start from singletons and move a vertex to the neighboring community with the best positive \u0394H."],["Restabilize","Requeue neighbors whose best move may have changed."],["Refine","Split each moved community into well-connected pieces without crossing its boundary."],["Compress","Turn refined pieces into weighted supernodes, repeat, and project labels back."]],pseudocode:["P_move \u2190 singleton_partition(G)","repeat until the local-move queue is empty:","    v \u2190 pop_queue()","    c* \u2190 argmax over neighbor communities c of \u0394H(v \u2192 c)","    if \u0394H(v \u2192 c*) > \u03b5: move v; requeue affected neighbors","P_refine \u2190 refine_inside_each_community(G, P_move, \u03b3)","G' \u2190 aggregate G by P_refine; carry P_move labels onto G'","repeat on G'; then project the final labels back to V"],invariant:"During refinement, a refined piece may merge only inside its parent P_move community. Aggregation therefore never forgets which coarse boundary constrained the refinement.",complexity:"With cached community totals, testing v costs roughly the degree of v, so one full local sweep is usually O(m). The number of sweeps and aggregate levels is data-dependent; Leiden is a heuristic, not a fixed-pass O(m) algorithm.",example:{title:"one edge and \u03b3 = 0.4",input:"Two singleton vertices u and v joined by one unit-weight edge.",trace:"Merging them gains one internal edge and pays \u03b3 for their one possible pair, so \u0394H = 1 \u2212 0.4 = 0.6 > 0.",output:"The local move joins {u,v}. At \u03b3 = 1.2, the same merge would lose 0.2 and be rejected."},misconception:["\u03b3 is just an animation speed or convergence tolerance.","\u03b3 changes the mathematical partition being optimized: larger \u03b3 favors smaller, denser communities."],checkpoint:["Why does Leiden aggregate refined pieces rather than the coarser move-phase communities?","Because refinement may expose a weak join inside one move-phase label. Collapsing the coarse label would make that weak join impossible to reconsider at higher levels."],production:"run_leiden.py uses leidenalg.CPMVertexPartition, default seed 1234, and two outer iterations. This browser explains one optimizer call at seed 42 and uses greedy libleidenalg-style refinement."}),t("leiden-mod",{title:"Leiden modularity: the same optimizer, a different score",intro:"The control flow is Leiden again. What changes is the question asked by every move: does this grouping contain more internal edge weight than a degree-preserving random graph would predict?",goal:"Find a partition with high modularity while using Leiden refinement to avoid badly connected intermediate communities.",output:"Original-vertex community labels; singleton groups are omitted by the repository wrapper.",prerequisites:["Vertex degree and total edge weight m","Expected value under a null model","Local search and graph contraction into weighted supernodes"],symbols:[["k_i","weighted degree of vertex i"],["2m","sum of all vertex degrees"],["\u03a3_tot(c)","sum of degrees of vertices currently in community c"],["\u0394Q(v\u2192c)","modularity change for moving v into c"]],phases:[["Model expectation","Use degrees to estimate how much internal weight a random configuration graph would create."],["Move","Compare v's observed edges into neighboring communities with that null-model penalty."],["Converge locally","Continue until no queued vertex has a positive move."],["Refine","Rebuild connected pieces inside every coarse community."],["Compress","Aggregate refined pieces, repeat at the next level, and project back."]],pseudocode:["P_move \u2190 singleton_partition(G)","while unstable vertices remain:","    v \u2190 next unstable vertex","    for c in {current block, neighboring blocks, empty block}:","        compute \u0394Q(v \u2192 c) from edge weights and degree totals","    commit the strict best positive move; requeue affected neighbors","P_refine \u2190 constrained_refinement(G, P_move)","aggregate by P_refine, retain P_move labels, repeat, project"],invariant:"The cached degree total for every community must equal the sum of degrees of its current members. If a move updates membership without updating that cache, every later \u0394Q is wrong.",complexity:"A cached local sweep is typically O(m), followed by O(n+m) aggregation. Repeated sweeps and levels make total runtime data-dependent. Modularity optimization is NP-hard, so the method seeks a local optimum.",example:{title:"two triangles joined by one bridge",input:"Six vertices form triangles {0,1,2} and {3,4,5}, plus bridge (2,3).",trace:"Each vertex has more observed edge weight inside its triangle than the degree null model expects. Moving a triangle vertex across the bridge usually loses internal edges and gains too little null-model advantage.",output:"A common local optimum is the two-triangle partition, although visit order can change the path."},misconception:["Leiden modularity has a resolution parameter on this page just like CPM.","This wrapper's modularity branch exposes no \u03b3. Its scale comes from the global 2m null model, which also creates the resolution limit."],checkpoint:["What does an empty local-move queue prove?","Only that no tested one-vertex move improves modularity at the current graph level. It does not prove a global optimum or finish the refinement and aggregation phases."],production:"run_leiden.py selects ModularityVertexPartition and performs two outer iterations. The page demonstrates one iteration and separately identifies the stronger convergence statement made by the paper."}),t("louvain",{title:"Louvain is greedy modularity search plus graph compression",intro:"There are only two phases, but they repeat at several scales. First improve labels on the current graph; then replace each community with a weighted supernode and solve the smaller graph.",goal:"Find a high-modularity partition quickly by combining local vertex moves with multilevel aggregation.",output:"The deepest-level community label projected back to every original vertex, followed by singleton removal in production.",prerequisites:["Modularity as observed internal weight minus degree-based expected weight","Adjacency lists and maps from community id to incident edge weight","Quotient graphs: replacing a block by one weighted vertex"],symbols:[["Q","modularity of the current partition"],["k_i,in(c)","weight of edges from vertex i into community c"],["\u03a3_tot(c)","total degree currently assigned to c"],["level","one local-move phase followed by one aggregation"]],phases:[["Initialize","Give every current-level vertex its own community."],["Sweep","Visit vertices and take the neighboring-community move with the largest positive \u0394Q."],["Repeat","Run more sweeps until a complete sweep makes no useful change."],["Renumber","Compress surviving community ids to a dense range."],["Aggregate","Sum weights between communities, then solve the resulting supergraph."]],pseudocode:["G_level \u2190 G","repeat:","    P \u2190 singleton_partition(G_level)","    repeat:","        changed \u2190 greedy_modularity_sweep(G_level, P)","    until not changed","    record P; G_level \u2190 aggregate(G_level, P)","until aggregation produces no modularity improvement","project all recorded labels back to the original vertices"],invariant:"Aggregation must preserve total edge weight: an edge inside one community becomes a self-loop, and all edges between two communities are summed into their superedge.",complexity:"A sparse local sweep is usually near O(m), and aggregation is O(n+m). The number of sweeps and levels is empirical. Exact modularity maximization is hard, so Louvain gives a fast local optimum rather than an optimality certificate.",example:{title:"two triangles become two supernodes",input:"Two triangles share one bridge edge.",trace:"Greedy moves first coalesce each triangle. Aggregation replaces the six vertices with two supernodes carrying self-loop weight 3 and bridge weight 1.",output:"The next level decides whether those two supernodes should remain separate; final labels are then projected to all six vertices."},misconception:["Once a community is created, Louvain can split it later at the same level.","A vertex can move locally, but after aggregation a community is one indivisible supernode. This is one reason Leiden adds an explicit refinement phase."],checkpoint:["Why keep self-loops when building the aggregate graph?","They store the internal edge weight already earned by a community. Dropping them would change modularity at the next level."],production:"The repository runs vendored C++ convert, louvain, and hierarchy executables. Its deterministic seed shim controls libc rand; the browser uses MT19937, so equal numeric seeds do not mean identical vertex orders."}),t("infomap",{title:"Infomap turns a random walk into a compression problem",intro:"Imagine transmitting the location of a random walker forever. A good community partition lets you reuse short local codewords inside modules and reserve a separate codebook for the rarer module changes.",goal:"Choose modules that minimize the expected number of bits needed to encode an infinite random walk.",output:"A module label for each vertex; modern Infomap may also return a hierarchy of nested modules.",prerequisites:["Markov chains and stationary probability","Shannon entropy H(p) = \u2212\u03a3 p log\u2082p","Greedy optimization and graph aggregation"],symbols:[["p_i","stationary probability of visiting vertex i"],["q\u21b7","total probability per step of exiting modules"],["p\u21bb_c","use rate of module c's local codebook"],["L(M)","map-equation code length for partition M"]],phases:[["Compute flow","Find how often the random walker visits each vertex and crosses each proposed boundary."],["Price a partition","Combine index-codebook entropy with each module-codebook entropy."],["Search","Test local joins or node moves and keep changes that reduce L(M)."],["Compress","Replace modules by supernodes while preserving flow between them."],["Recurse","Search for useful submodules and project the hierarchy back to vertices."]],pseudocode:["p \u2190 stationary_distribution(G)","M \u2190 singleton_modules(V)","repeat:","    for each candidate local change x:","        evaluate \u0394L using updated exit and codebook rates","    apply a change with \u0394L < 0","until no tested change shortens the description","aggregate modules and repeat; optionally search within modules"],invariant:"Every codebook distribution must normalize to one after dividing by that codebook's use rate. Raw visit and exit rates are not themselves valid symbol probabilities until normalized.",complexity:"One power-iteration pass over a sparse graph is O(m); T passes cost O(Tm). Local search and hierarchy construction add data-dependent sweeps. The maintained Infomap engine contains substantially more tuning phases than this teaching trace.",example:{title:"a walker trapped in two rooms",input:"Two triangles are joined by one bridge.",trace:"The walker frequently moves inside a triangle but rarely crosses the bridge. Two module codebooks are reused many times, while the index codebook is used only on a crossing.",output:"The two-triangle partition can require fewer average bits per step than one global codebook or six singleton modules."},misconception:["Infomap directly maximizes edge density or modularity.","Its objective is coding length for flow. Direction, weights, and teleportation can change flow even when the unweighted topology looks similar."],checkpoint:["Why can a low-conductance bridge help compression?","It makes module exits rare. Rare index-codebook use can outweigh the extra cost of maintaining separate local codebooks."],production:"run_infomap.py invokes maintained Infomap 2.9.2 defaults. The visible optimizer is a deliberately smaller 2008-paper-style explanation of the objective, not a replay of every modern fine/coarse-tuning phase."}),t("ikc",{title:"IKC repeatedly removes the strongest remaining cores",intro:"A k-core is not a community label by itself; it is a maximal region where every remaining vertex has at least k neighbors in that region. IKC repeatedly extracts components at the largest residual core number.",goal:"Find dense center components in descending core strength while applying the paper's validity tests.",output:"A partial partition of accepted core components. Lower-core peripheral vertices may remain unassigned in the shipped Stage-1 implementation.",prerequisites:["Vertex degree and induced subgraphs","Queue-based peeling for k-core decomposition","Connected components after filtering vertices"],symbols:[["core(v)","largest k for which v belongs to a k-core"],["k_max","largest core number in the current residual graph"],["k-valid","paper test requiring a component to be large enough relative to k"],["residual","vertices not removed by earlier accepted or rejected rounds"]],phases:[["Decompose","Compute core numbers on the current residual graph."],["Select","Keep vertices with core number k_max."],["Separate","Find connected components induced by those vertices."],["Validate","Apply k-validity and the configured modularity-validity gate."],["Remove","Emit accepted components, remove processed vertices, and repeat."]],pseudocode:["R \u2190 all vertices","while R is not empty:","    core \u2190 core_numbers(G[R])","    k \u2190 max_v core[v]","    candidates \u2190 components induced by {v : core[v] = k}","    for C in candidates:","        if k_valid(C, k) and modular_valid(C): emit C","    remove the processed maximum-core vertices from R"],invariant:"Core numbers must be recomputed on the residual graph. Reusing numbers from the original graph after removals can overstate the support that a vertex still has.",complexity:"One core decomposition is O(n+m). The shipped code recomputes it over multiple residual rounds, so total work is the sum of the remaining graph sizes rather than one O(n+m) pass.",example:{title:"triangle with one leaf",input:"Edges form triangle 0\u20131\u20132\u20130 and leaf edge 2\u20133.",trace:"The triangle vertices have core number 2; the leaf has core number 1. The maximum-core induced component is {0,1,2}.",output:"The triangle is considered first. Vertex 3 can remain unassigned because the shipped code does not implement the later periphery-assignment stage."},misconception:["A vertex's core number is simply its degree.","Core number is recursive: neighbors that are peeled away no longer support the vertex. A high-degree vertex can have a low core number."],checkpoint:["Why find connected components after selecting all k_max vertices?","The maximum core can contain disconnected regions. They are separate candidate centers and must be validated independently."],production:"src/ikc/run_ikc.py implements this extraction stage, but modular() immediately returns a positive constant and the paper's p-validity/periphery assignment is absent. The strict-paper toggle is teaching-only."}),t("sbm-flat-best",{title:"Model selection means fit each hypothesis, then compare total descriptions",intro:"The selector is not another clustering algorithm. It runs several statistical models independently and compares how many nats each model needs to describe both the graph and its own parameters.",goal:"Choose among flat degree-corrected, traditional, and planted-partition SBM hypotheses using commensurate minimum-description-length scores.",output:"The com.csv from the model with the smallest canonical graph-tool state entropy.",prerequisites:["Likelihood: how well parameters explain observed data","Regularization or priors: a cost for model complexity","argmin over comparable scalar scores"],symbols:[["b_i","block assigned to vertex i"],["e_rs","number of edges between blocks r and s"],["\u03a3","complete description length; smaller is better"],["DC / NDC / PP","degree-corrected, traditional, and planted-partition model families"]],phases:[["Clean input","Remove loops and parallel edges exactly as the wrapper does."],["Fit DC","Optimize a flat SBM that conditions on heterogeneous degrees."],["Fit NDC","Optimize a flat SBM that expects vertices in one block to have similar rates."],["Fit PP","Optimize an assortative model with shared within/between structure."],["Compare","Read the three canonical entropy files and select their argmin; file order breaks an exact tie."]],pseudocode:["scores \u2190 empty map","for model in {DC, NDC, PP}:","    state[model] \u2190 minimize_description_length(G, model)","    scores[model] \u2190 state[model].entropy()","winner \u2190 argmin_model scores[model]","return membership(state[winner])"],invariant:"Only scores produced under compatible coding conventions may be compared. A smaller number from a simplified browser formula does not defeat a larger canonical graph-tool entropy.",complexity:"The selector pays for three independent inference runs; its own argmin is O(1). Each fit uses a data-dependent multilevel MCMC heuristic, so the model fitting\u2014not selection\u2014dominates runtime.",example:{title:"three canonical fit files",input:"DC writes 104.2 nats, NDC writes 101.7, and PP writes 110.5.",trace:"The selector performs no new graph moves. It reads the files and computes argmin{104.2,101.7,110.5}.",output:"NDC wins and its com.csv is linked as the selector output."},misconception:["The model with the most parameters should always fit best and therefore win.","Description length charges for parameters and partitions as well as data misfit. Extra flexibility must save enough graph bits to pay for itself."],checkpoint:["Why is comparing only the final likelihood insufficient?","A more flexible model can increase likelihood by overfitting. The description-length prior and parameter costs make model complexity part of the comparison."],production:"choose_best_sbm.py compares canonical graph-tool entropy.txt files. The three browser curves use simplified objectives and a shared short schedule only to explain assumptions; their winner is not a production prediction."}),t("sbm-flat-dc",{title:"A degree-corrected SBM separates popularity from mixing pattern",intro:"Two vertices can belong to the same block even when one is a hub and the other has few edges. Degree correction models those individual activity levels instead of forcing the block structure to explain them.",goal:"Infer flat blocks whose connection patterns differ after conditioning on heterogeneous vertex degrees.",output:"One base-level block label per vertex and a complete description length for that fitted state.",prerequisites:["Block matrices and sufficient statistics","Log-likelihoods and factorials via log \u0393","Metropolis-Hastings acceptance for discrete state changes"],symbols:[["b_i","current block of vertex i"],["e_rs","edge count between blocks r and s"],["e_r","sum of half-edge counts incident to block r"],["\u0394\u03a3","new description length minus old; negative is an improvement"]],phases:[["Initialize","Assign vertices to candidate blocks and build n_r and e_rs."],["Propose","Choose a vertex and a candidate destination block."],["Update locally","Compute how only incident edge counts and block sizes would change."],["Accept","Take every \u0394\u03a3\u22640 move and some uphill moves according to exp(\u2212\u03b2\u0394\u03a3)."],["Sweep","Visit vertices repeatedly, remove empty labels, and return the best state."]],pseudocode:["b \u2190 initial block assignment","cache n_r, e_rs, e_r from (G, b)","for sweep = 1..S:","    for vertex v in visit_order:","        s \u2190 propose_destination(v, b, G)","        \u0394\u03a3 \u2190 local_description_change(v, b[v], s, caches)","        accept with probability min(1, exp(\u2212\u03b2\u0394\u03a3) \xd7 HastingsRatio)","        if accepted: update b and all affected caches"],invariant:"The block matrix must count every undirected edge exactly once under one consistent diagonal convention. Local cache updates must match a full recomputation of \u03a3.",complexity:"With sparse local statistics, scoring one move is proportional to deg(v) plus proposal bookkeeping, making a sweep roughly O(n+m). The number of sweeps, merge levels, and restarts is heuristic.",example:{title:"a hub and a leaf may share a role",input:"Vertices h and \u2113 both connect mostly to block B, but h has degree 20 and \u2113 degree 2.",trace:"Degree correction accounts for their different activity levels. The evidence for their block is the similar destination pattern, not equal degree.",output:"h and \u2113 can remain in one block without creating a special hub block solely to explain degree 20."},misconception:["Degree-corrected means the algorithm normalizes the adjacency matrix first.","It changes the generative model: vertex degrees are conditioned on or explicitly parameterized while block mixing is inferred."],checkpoint:["Why can \u0394\u03a3 be computed without rescoring every edge?","Moving v changes only v's block size and counts for block pairs touched by edges incident to v. All other sufficient statistics cancel in the difference."],production:"graph-tool uses neighbor-informed proposals, a Hastings correction, multilevel merges, and its canonical priors. The browser uses fixed B=8 uniform proposals and exact combinatorial terms, so it is objective-shaped but not trajectory-equivalent."}),t("sbm-flat-ndc",{title:"The traditional SBM treats degree homogeneity as evidence",intro:"Without degree correction, all vertices in a block share the same block-to-block connection rates. A large degree difference can therefore be evidence that two vertices should not share a block.",goal:"Infer flat blocks under the hypothesis that vertices in one block are statistically exchangeable, including their expected degrees.",output:"One block label per vertex plus the fitted traditional-SBM description length.",prerequisites:["Bernoulli or Poisson edge models between block pairs","Combinatorial counts for partitions and edge matrices","Metropolis state updates"],symbols:[["n_r","number of vertices assigned to block r"],["e_rs","observed edge count between r and s"],["p_rs","shared connection rate for vertices in block pair (r,s)"],["\u03a3","graph cost plus partition and parameter costs"]],phases:[["Count","Build block sizes and the block-to-block edge matrix."],["Propose","Select one vertex and a possible new block."],["Recount locally","Move its incident edge contributions between matrix rows and columns."],["Decide","Use the description-length change in the MCMC acceptance rule."],["Simplify","Continue sweeps and remove empty block labels."]],pseudocode:["b \u2190 initial_assignment(B candidate blocks)","stats \u2190 {n_r, e_rs}","repeat for a sweep budget:","    v \u2190 next vertex","    s \u2190 proposed block","    \u0394\u03a3 \u2190 NDC_cost_after_local_move(v, s) \u2212 current_cost","    if metropolis_accept(\u0394\u03a3): commit move and update stats","return best visited assignment and its \u03a3"],invariant:"\u03a3_r n_r must always equal n, and the total represented edge count in e_rs must always equal m. Those are quick sanity checks after every accepted move.",complexity:"A cached sweep is roughly O(n+m), but inference uses multiple sweeps and merge levels. The fixed browser sweep count is a teaching budget, not a convergence guarantee.",example:{title:"a hub can create a block",input:"A star has one degree-8 center and eight degree-1 leaves.",trace:"One shared within-block rate cannot explain both roles well. Separating the center from the leaves can reduce graph coding cost enough to pay for another block.",output:"The NDC model may infer center and leaf blocks even when the distinction is degree rather than a dense community boundary."},misconception:["Non-degree-corrected is always the simpler, safer default.","It is a stronger scientific assumption. It is useful when within-block degree similarity is meaningful and misleading when degree heterogeneity is nuisance variation."],checkpoint:["What observation most strongly separates NDC from DC behavior?","Large degree variation among vertices that otherwise connect to the same kinds of blocks. DC can absorb it; NDC often spends extra blocks explaining it."],production:"run_sbm.py calls graph-tool with deg_corr=False. The page's uniform proposal, fixed initialization, and short exact-\u03a3 sampler explain the model but do not reproduce graph-tool's optimizer or entropy.txt."}),t("sbm-flat-pp",{title:"The planted-partition model compresses the block matrix to two roles",intro:"A general SBM can give every block pair a different rate. The assortative planted-partition model instead asks a narrower question: are edges generally more likely within groups than between groups?",goal:"Infer a flat assortative partition using a constrained within-group versus between-group mixing model.",output:"One group label per vertex and a planted-partition description length.",prerequisites:["Assortative communities: within-group edges are favored","Sufficient statistics for internal and external edges","The bias-variance tradeoff from restricting a model"],symbols:[["e_in","total edges whose endpoints share a block"],["e_out","total edges crossing block boundaries"],["B","number of occupied groups"],["\u03a3_PP","description length under planted-partition assumptions"]],phases:[["Summarize","Reduce detailed block mixing to within-group and between-group evidence."],["Propose","Move one vertex to a candidate group."],["Update","Reclassify its incident edges as internal or external."],["Accept","Balance graph compression against the cost of the partition and parameters."],["Return","Keep the best assortative state found by the search."]],pseudocode:["b \u2190 initial partition","cache e_in, e_out, block sizes, degree terms","for each MCMC sweep:","    for vertex v:","        s \u2190 proposed destination group","        \u0394\u03a3_PP \u2190 cost change from reclassifying v's incident edges","        accept or reject with the MCMC rule","return minimum-\u03a3_PP state visited"],invariant:"Every edge is classified as exactly one of internal or external, so e_in + e_out = m. A move must flip that classification only for edges incident to the moved vertex.",complexity:"Local scoring is proportional to deg(v), so one cached sweep is near O(n+m). Search length remains data-dependent. The stronger PP restriction can be faster or statistically cheaper, but it cannot express arbitrary disassortative block matrices.",example:{title:"two dense pairs",input:"Edges (0,1) and (2,3) are strong internal evidence, with only one cross edge (1,2).",trace:"Partition {{0,1},{2,3}} classifies two edges as internal and one as external. A one-block partition makes all three internal but loses the evidence for two separately dense groups.",output:"The two-group state can win when its extra partition cost is smaller than the saved assortative coding cost."},misconception:["PPBlockState is just a general SBM with a different color palette.","It is a restricted statistical model. That restriction is useful evidence when assortativity is plausible and a bad fit for bipartite or core\u2013periphery structure."],checkpoint:["Why might a restricted PP model beat a more flexible SBM?","If the graph is genuinely assortative, PP can describe it with fewer parameters. The reduced model cost can outweigh the flexible model's slightly better raw fit."],production:"graph-tool PPBlockState includes degree information and non-uniform priors absent from the browser's simpler two-rate objective. Browser \u03a3_PP values therefore must not be compared numerically with production entropy."}),t("sbm-nested-best",{title:"Nested model selection compares complete hierarchies",intro:"A nested SBM does not stop after grouping vertices. It builds a block graph, groups that graph again, and charges for the entire hierarchy. The selector compares two complete hierarchical hypotheses.",goal:"Choose whether degree correction improves the total description of a recursively modeled block hierarchy.",output:"Level-0 membership from the lower-entropy canonical nested state, even though the selected score includes every level.",prerequisites:["Flat SBM sufficient statistics","Multilevel or recursive data structures","Model selection by complete description length"],symbols:[["G_0","original vertex graph"],["G_\u2113","block multigraph produced at hierarchy level \u2113"],["B_\u2113","number of occupied blocks at level \u2113"],["\u03a3_nested","sum of graph and hierarchy coding terms across levels"]],
phases:[["Fit bases","Infer separate DC and NDC partitions on the original graph."],["Build upward","Turn each base partition into a weighted block graph."],["Group again","Infer blocks of blocks until the top has one group."],["Price all levels","Include every partition and block-graph term in \u03a3_nested."],["Select","Compare canonical DC and NDC hierarchy entropies and emit winner level 0."]],pseudocode:["for model in {nested DC, nested NDC}:","    state[model] \u2190 fit_level_0(G, model)","    while current level has more than one block:","        G_next \u2190 block_graph(current level)","        append fit_blocks(G_next) to state[model]","    score[model] \u2190 entropy_of_complete_hierarchy(state[model])","winner \u2190 argmin score; return winner.level(0).membership"],invariant:"An upper-level vertex represents exactly one occupied block below it. Edge multiplicities and self-loops in G_\u2113 must preserve the entire lower-level block matrix.",complexity:"Selection itself is constant work after two independent nested fits. Fitting is a multilevel MCMC heuristic; runtime is the sum of sweeps over all hierarchy graphs and cannot be inferred from only the level-0 node count.",example:{title:"four pairs inside two regions",input:"Eight vertices form four tight pairs; pairs 0\u20131 and 2\u20133 interact more strongly within their respective regions.",trace:"Level 0 can contain four pair-blocks. Level 1 can group those into two region-blocks. Level 2 contains one root.",output:"The selector still emits the four level-0 labels, but its score includes the two-region explanation and root."},misconception:["The selector should compare only the two level-0 entropy curves shown by the walker.","The production decision uses the full hierarchy entropy. An attractive base partition can lose after upper-level model costs are included."],checkpoint:["Why can hierarchy reduce the flat SBM resolution problem?","Large-scale structure is encoded on smaller block graphs, so evidence for fine groups does not compete only against one global flat parameter scale."],production:"nested_best_pipeline.sh compares two graph-tool state.entropy() files. The browser rebuilds upper levels for explanation and fully walks only level 0, so its qualitative verdict is not the pipeline decision."}),t("sbm-nested-dc",{title:"Nested DC-SBM models degree variation at the leaves and structure above",intro:"At level 0, degree correction separates individual activity from block mixing. Above level 0, each vertex is itself a block from below, and the algorithm recursively explains the resulting edge-count graph.",goal:"Infer a multiscale hierarchy while allowing heterogeneous degrees among original vertices in the same base block.",output:"Base-level block labels plus an internal hierarchy whose complete entropy is used for inference and comparison.",prerequisites:["Degree-corrected flat SBM moves","Weighted multigraphs with self-loops","Trees or arrays of parent mappings between levels"],symbols:[["b_i^(0)","base block of original vertex i"],["e_rs^(\u2113)","edge multiplicity between blocks at level \u2113"],["parent_\u2113(r)","block above level-\u2113 block r"],["L","number of hierarchy levels including the root"]],phases:[["Fit leaves","Use DC-SBM moves to obtain a base partition."],["Rebuild","Create the block multigraph with exact edge multiplicities."],["Fit parents","Group block-vertices on the smaller graph."],["Propagate","If a lower block moves or disappears, rebuild affected upper structure."],["Stop","Finish at a single root and project base labels to original vertices."]],pseudocode:["level[0] \u2190 fit_DC_SBM(G)","\u2113 \u2190 0","while occupied_blocks(level[\u2113]) > 1:","    G[\u2113+1] \u2190 aggregate G[\u2113] by level[\u2113]","    level[\u2113+1] \u2190 fit_SBM(G[\u2113+1])","    \u2113 \u2190 \u2113 + 1","return level[0].membership and all parent maps"],invariant:"Following parent pointers from any original vertex must end at exactly one root, with no skipped or dangling occupied block at any level.",complexity:"A level-0 teaching sweep is near O(n+m); upper levels operate on progressively smaller weighted graphs. Canonical graph-tool optimization couples merge and MCMC moves across levels, so total runtime is data-dependent.",example:{title:"hub variation inside a multiscale region",input:"Each of four local groups contains one hub and several leaves, and pairs of groups form two larger regions.",trace:"DC avoids splitting each local hub from its leaves solely by degree. The nested levels can then group local blocks into the two larger regions.",output:"The hierarchy represents individual degree variation, four local roles, two regions, and one root at different layers."},misconception:["Every upper level is another partition of the original vertices computed from scratch.","Upper levels partition the occupied blocks from the level below. Original-vertex membership at an upper level is obtained by composing parent maps."],checkpoint:["What information must an aggregate edge weight preserve?","The number or total weight of original lower-level edges between the represented blocks, including internal edges as self-loops."],production:"run_sbm.py uses minimize_nested_blockmodel_dl with deg_corr=True. The browser's base sampler and explanatory upper rebuild omit graph-tool's neighbor proposals, Hastings factors, and coupled hierarchy optimizer."}),t("sbm-nested-ndc",{title:"Nested NDC-SBM combines exchangeable base blocks with a hierarchy",intro:"The recursive machinery is the same as nested DC-SBM, but the base hypothesis is stronger: vertices in one leaf block should have similar connection rates, including expected degree.",goal:"Infer a multiscale hierarchy under a non-degree-corrected base model.",output:"Level-0 traditional-SBM labels and their recursively modeled parent hierarchy.",prerequisites:["Traditional flat SBM and its degree-homogeneity assumption","Block multigraph aggregation","Recursive partitions and description-length regularization"],symbols:[["n_r^(0)","number of original vertices in base block r"],["G_1","weighted graph whose vertices are occupied base blocks"],["B_\u2113","occupied blocks at hierarchy level \u2113"],["\u03a3","complete nested non-degree-corrected description length"]],phases:[["Fit base","Group exchangeable original vertices without degree correction."],["Aggregate","Turn occupied groups into a weighted block graph."],["Fit upper graph","Find structure among those block-vertices."],["Repeat","Continue aggregation until a root is reached."],["Compose","Use parent mappings to explain every vertex at every scale."]],pseudocode:["P0 \u2190 fit_NDC_SBM(G)","hierarchy \u2190 [P0]","while last(hierarchy) has more than one occupied block:","    H \u2190 aggregate previous graph by last(hierarchy)","    append fit_block_partition(H) to hierarchy","return P0 and hierarchy"],invariant:"At level 0, both block sizes and edge counts must remain consistent after a move; above it, every parent mapping must cover exactly the occupied child blocks.",complexity:"The browser's cached base sweep is near O(n+m), followed by smaller upper graphs. Multiple sweeps, level rebuilds, and graph-tool's canonical merge search make the complete runtime heuristic.",example:{title:"degree classes and regions",input:"A network has high-degree centers and low-degree leaves inside two geographic regions.",trace:"NDC may first separate centers from leaves because their expected degrees differ, then an upper level can group those role blocks by region.",output:"The hierarchy can be meaningful, but its leaves answer a different question from degree-corrected leaves."},misconception:["Nesting automatically fixes every modeling mistake at level 0.","Hierarchy regularizes scale, but it does not remove the base model's degree-homogeneity assumption. An inappropriate leaf model can still create misleading role blocks."],checkpoint:["When should nested NDC and nested DC disagree most?","When vertices with similar mixing patterns have very different degrees. NDC treats that variation as block evidence; DC can treat it as individual activity."],production:"graph-tool is called with deg_corr=False and scores the full canonical hierarchy. The visible upper-level diagrams teach nesting but are not a move-by-move port of that optimization."}),t("cc",{title:"CC repairs labels using only graph reachability",intro:"This is a deterministic cleanup algorithm, not a fresh community detector. It trusts the input labels, deletes edges that cross those labels, and splits any label whose vertices are no longer connected.",goal:"Turn every input cluster into connected components without merging vertices from different original labels.",output:"Connected non-singleton pieces labeled in FIFO discovery order; singleton pieces are absent from production com.csv.",prerequisites:["Breadth-first or depth-first search","Induced subgraphs and edge filtering","Connected components in O(n+m)"],symbols:[["z_v","input cluster label of vertex v"],["E_same","edges (u,v) with z_u = z_v"],["G_z","graph after removing all cross-label edges"],["component","maximal set of mutually reachable vertices in G_z"]],phases:[["Read labels","Attach each input membership id to its vertex."],["Strip","Remove every edge whose endpoints have different labels."],["Search","Run BFS/DFS to find connected components of the stripped graph."],["Filter","Discard components containing only one vertex."],["Emit","Assign dense output labels in the binary's queue order."]],pseudocode:["E_same \u2190 {(u,v) in E : z[u] = z[v]}","visited \u2190 empty set; output \u2190 []","for vertex s in binary iteration order:","    if s not visited:","        C \u2190 BFS((V, E_same), s)","        if |C| > 1: append C to output","assign output labels 0..|output|\u22121"],invariant:"A search frontier can contain only vertices with the seed's original label, because every cross-label edge was removed before BFS begins.",complexity:"Edge filtering plus connected components is O(n+m) time and O(n+m) storage for an adjacency-list representation. No mincut, random number generator, or iterative optimizer is needed.",example:{title:"one broken input label",input:"Vertices {0,1,2} all have label A, but the only retained edge is (0,1).",trace:"After cross-label stripping, BFS finds components {0,1} and {2}.",output:"{0,1} is emitted as a cluster; singleton {2} is rejected and disappears from the production CSV."},misconception:["CC tests whether a cluster is strongly or densely connected.","It tests ordinary reachability only. A single bridge is sufficient to keep two large regions in one component."],checkpoint:["Can CC ever merge two different input labels?","No. It deletes cross-label edges and only splits existing labels. It is a refinement operation, never a merger."],production:"src/cc/pipeline.sh invokes MincutOnly with criterion 0, which takes the simple connected-components branch. VieCut and the recorded wrapper seed are behaviorally irrelevant here."}),t("wcc",{title:"WCC recursively turns a mincut inequality into clusters",intro:"Connectedness asks whether at least one path exists. WCC asks a stronger quantitative question: how many edges must be removed to disconnect this candidate, and is that number larger than a size-dependent threshold?",goal:"Recursively split every candidate whose global minimum cut does not strictly exceed f(n).",output:"Non-singleton pieces that pass the selected well-connectedness threshold.",prerequisites:["FIFO queues and recursive divide-and-conquer","Global minimum cut as the smallest capacity disconnecting a graph","Connected components on each side after a cut"],symbols:[["\u03bb(S)","global mincut value of the subgraph induced by candidate S"],["f(|S|)","required connectivity threshold for a candidate of this size"],["\u03b5 = 10\u207b\u2079","binary equality band; equality fails the strict test"],["Q","FIFO queue of candidates still requiring a decision"]],phases:[["Seed","Strip input cross-label edges and enqueue their non-singleton components."],["Pop","Remove the next candidate S from the FIFO."],["Cut","Compute \u03bb(S) and one most-balanced minimum-cut bipartition."],["Decide","Keep S only when \u03bb(S) is strictly above f(|S|) outside \u03b5."],["Split","Otherwise find connected pieces on both cut sides and enqueue non-singletons."]],pseudocode:["Q \u2190 non_singleton_components(after stripping input labels)","answer \u2190 []","while Q is not empty:","    S \u2190 Q.pop_front()","    (\u03bb, A, B) \u2190 most_balanced_global_mincut(G[S])","    if \u03bb > f(|S|) and not close(\u03bb, f(|S|), 1e\u22129): append S","    else: enqueue non-singleton components of G[A], then G[B]","return answer"],invariant:"Queued candidates are disjoint subsets of one original input label. Once a vertex falls onto a discarded singleton side, it never re-enters a later candidate.",complexity:"The BFS bookkeeping is linear in the processed subgraphs, but exact global mincut dominates. Recursion can call mincut on several descendants, so total cost is the sum of those mincut instances rather than one O(n+m) pass.",example:{title:"twelve vertices joined by one bridge",input:"Two internally dense six-vertex regions share one bridge; use f(n)=log\u2081\u2080(n).",trace:"The whole candidate has \u03bb=1, while log\u2081\u2080(12)\u22481.079. Because 1 does not strictly exceed 1.079, WCC cuts the bridge and enqueues the two sides.",output:"Each side is tested independently and may become a survivor if its own mincut clears log\u2081\u2080(6)."},misconception:["A cluster passes when \u03bb(S) \u2265 f(|S|).","The binary requires a strict excess and explicitly treats values within 10\u207b\u2079 of the threshold as failure."],checkpoint:["Why run connected components on a mincut side instead of enqueueing the side directly?","Removing the cut can leave one side internally disconnected. Each connected piece is an independent future candidate, and singleton pieces are discarded."],production:"The wrapper defaults to log10(n). main.cpp seeds VieCut once with 0; every later cut advances the same RNG stream. The wrapper's --seed is metadata only, while the page's nonzero seed control is an experiment."}),t("cm",{title:"CM alternates structural tests with a base clustering algorithm",intro:"WCC always accepts or splits a candidate. CM adds a feedback loop: when a candidate fails its mincut test, it runs a chosen community detector separately on the two sides and sends the resulting children back through the same test.",goal:"Modify an existing clustering until each surviving descendant passes a mincut threshold, using a base detector to reorganize failed sides.",output:"Surviving binary-core clusters; the paper's external pruning and minimum-size analysis can further filter them later.",prerequisites:["Queues and lineage trees","Global mincut and induced subgraphs","A black-box base clustering function that returns labels on a subgraph"],symbols:[["S","current candidate cluster"],["A,B","two sides of a selected global mincut"],["base(G[A])","new clustering produced inside cut side A"],["history","parent/child records explaining how outputs descend from inputs"]],phases:[["Prepare","Strip cross-label edges and seed candidates from connected components."],["Test","Compute the candidate's global mincut and threshold."],["Keep","If the strict inequality passes, add the candidate to the survivor list."],["Recluster","If it fails, run the base algorithm independently on each cut side."],["Continue","Enqueue nontrivial child clusters and record their lineage."],["Postprocess","Optionally apply the paper pipeline's degree-band and size filters."]],pseudocode:["Q \u2190 initial connected candidate clusters","while Q is not empty:","    S \u2190 Q.pop_front()","    (\u03bb, A, B) \u2190 global_mincut(G[S])","    if \u03bb strictly clears f(|S|): keep S","    else:","        for side in {A, B}:","            children \u2190 base_cluster(G[side])","            enqueue nontrivial children and record parent S","return survivors and history"],invariant:"Every child is contained in exactly one failed parent and one cut side. Re-clustering may subdivide a side, but it must never introduce a vertex from outside that side.",complexity:"Each failed candidate pays for one exact mincut plus up to two base-detector calls. The recursion tree and chosen detector dominate runtime; there is no useful single O(m) bound for the complete workflow.",example:{title:"a failed side contains two latent groups",input:"Candidate S fails across cut A|B. Side A contains two dense groups that the original label merged.",trace:"CM runs the base detector on G[A], obtains A\u2081 and A\u2082, and enqueues them separately. WCC would have enqueued A as one component if A remained connected.",output:"Survivors can reflect both mincut evidence and the base algorithm's finer partition, with history linking them back to S."},misconception:["CM is only WCC with a differently named threshold.","The base re-clustering step changes the recursion: failed cut sides can be reorganized into several children before the next mincut test."],checkpoint:["Why must the page name the chosen base algorithm?","Because CM is not fully specified without it. Different base detectors can produce different children, lineage trees, runtimes, and final survivors."],production:"src/cm/pipeline.sh accepts three base algorithms and defaults to 0.2\u221an, while the paper presentation uses log10(n). The page opens on the paper rule and separately identifies external pruning that the C++ core does not perform."}),t("viecut",{title:"VieCut accelerates exact mincut without contracting unsafe edges",intro:"The important distinction is proof versus guess. Heuristics may find a good upper bound quickly, but an edge is contracted only when a safety test proves that no minimum cut of interest needs to separate its endpoints.",goal:"Compute an exact global mincut, represent all equal global mincuts as a cactus, and select a most-balanced one for WCC/CM.",output:"The exact cut value and one balanced bipartition mapped from contracted ids back to caller vertex ids.",prerequisites:["Union-find and graph contraction","s\u2013t max-flow/mincut and residual graphs","Strongly connected components and recursive graph decomposition"],symbols:[["\u03bb","exact global minimum cut value"],["U","current upper bound on \u03bb from a heuristic cut"],["capacity","unit edge weight in the deployed MinCutCustom adapter"],["cactus","compact graph in which each global mincut is one bridge or two edges on a cycle"]],phases:[["Adapt","Build the deployed undirected unit-weight graph and remember original ids."],["Bound","Use fast heuristics to obtain an upper bound U on the optimum."],["Contract safely","Apply certificate-based tests and union only endpoints proven inseparable by a better cut."],["Probe exactly","Run max-flow/mincut computations on the reduced stable kernel."],["Build cactus","Use residual SCC structure and recursion to encode all cuts of value \u03bb."],["Balance","Search cactus cuts for the side closest to half the original vertices, then expand ids."]],pseudocode:["H \u2190 deployed_unit_weight_graph(G); remember original vertex sets","U \u2190 heuristic_cut_upper_bound(H)","repeat:","    safe_edges \u2190 certify_edges_not_crossed_by any cut of value \u2264 U","    H \u2190 contract(H, safe_edges)","until no certified contraction remains","\u03bb and residual probes \u2190 exact_mincut_work(H, U)","C \u2190 recursively_build_cactus(residual probes, \u03bb)","side \u2190 most_balanced_cut(C); return expand(side), \u03bb"],invariant:"Every contracted supernode owns a disjoint set of original vertices, and those sets partition the active caller vertices. A contraction must preserve \u03bb; an upper bound alone is never a contraction proof.",complexity:"Graph scans and union-find operations are near-linear, but exact max-flow probes dominate worst-case work. VieCut's contribution is aggressive safe reduction and parallel/practical engineering, not a claim that exact mincut is merely one BFS.",example:{title:"two triangles with one bridge",input:"Two unit-weight triangles are connected by one edge.",trace:"The bridge cut has value 1, giving U=1. Internal triangle edges can be grouped only when the contraction tests certify safety. The exact phase confirms \u03bb=1; the cactus represents the bridge cut.",output:"The balanced side contains one triangle and maps back to its three caller vertex ids."},misconception:["VieCut may contract any heavy-looking edge because the result is only approximate.","This deployed path is exact. Heuristics tighten U, while certificate conditions protect every contraction needed for correctness."],checkpoint:["Why construct a cactus after already knowing \u03bb?","\u03bb gives only the optimum value. WCC/CM also need a bipartition, and several equal cuts may exist. The cactus represents all of them so the adapter can choose the most-balanced one."],production:"MinCutCustom forces all input edges to weight 1, threads=1, and a process-level MT19937 seed of 0. This page traces the cactus route as an exact primitive; community recursion belongs to WCC or CM, not VieCut itself."}),e.COMDET_UNDERGRAD_GUIDES=r,a()}(window);